import{aujourdhui}from"./chunk-CVSPVNUI.js";import{ecrire,lire}from"./chunk-U3K53GUR.js";import{RACINE}from"./chunk-MENTKLMX.js";var MESSAGES=[["bravo","Bon travail cette semaine, continue comme ça."],["progres","Tu progresses, ça se voit. Garde le rythme."],["revoir","Pense à revoir le cours avant le prochain contrôle."],["niveau1","Refais les exercices de niveau 1 avant de passer au niveau 2."],["methode","Relis la méthode, puis refais l'exercice sans regarder la correction."],["sans-indice","Essaie d'abord sans indice : tu sais plus de choses que tu ne crois."],["correction","Prends le temps de lire la correction en entier, pas seulement le résultat."],["controle-blanc","Fais le contrôle blanc du chapitre en conditions réelles."],["labo","Passe par les labos du chapitre : manipuler aide à comprendre."],["voir","Viens me voir si tu bloques, c'est fait pour ça."],["pause","N'oublie pas les pauses : 25 minutes de travail, 5 de repos."],["regulier","Dix minutes chaque jour valent mieux qu'une heure la veille."]],NATURES=[["controle","Contrôle"],["devoir","Devoir à rendre"],["oral","Évaluation orale"],["blanc","Épreuve blanche"],["tp","TP noté"],["rattrapage","Rattrapage"]],TYPES={exercice:"Exercice conseillé",cours:"Point de cours",echeance:"Échéance",devoir:"Devoir",message:"Message"},ICONES={exercice:"✎",cours:"📖",echeance:"📅",devoir:"📝",message:"💬"},CLE_CLASSES="classes-rejointes",CLE_FAIT="carnet-fait",cleCarnet=code=>"carnet:"+String(code||"").toUpperCase();function profs(){return lire(CLE_CLASSES,[])}function rejoindre(c){let l=profs().filter(x=>x.code!==c.code);return l.push({code:c.code,prof:c.prof,matiere:c.matiere,classe:c.classe||"",niveau:c.niveau||"",depuis:aujourdhui()}),ecrire(CLE_CLASSES,l),l}function quitter(code){ecrire(CLE_CLASSES,profs().filter(x=>x.code!==code))}function items(code){return lire(cleCarnet(code),[])}function publier(code,item){let l=items(code);return l.push(Object.assign({id:"i"+Date.now().toString(36)+Math.random().toString(36).slice(2,6),date:aujourdhui()},item)),ecrire(cleCarnet(code),l),l}function retirer(code,id){ecrire(cleCarnet(code),items(code).filter(x=>x.id!==id))}function faits(){return new Set(lire(CLE_FAIT,[]))}function setFait(id,oui){let f=faits();oui?f.add(id):f.delete(id),ecrire(CLE_FAIT,[...f])}function tout(){return profs().map(pr=>({prof:pr,items:trier(items(pr.code))}))}function trier(l){let rang={echeance:0,devoir:0,exercice:1,cours:2,message:3};return l.slice().sort((a,b)=>rang[a.type]===0&&rang[b.type]===0?(a.echeance||"").localeCompare(b.echeance||""):rang[a.type]!==rang[b.type]?rang[a.type]-rang[b.type]:(b.date||"").localeCompare(a.date||""))}function echeancesAVenir(){let auj=aujourdhui();return tout().flatMap(r=>r.items.filter(i=>(i.type==="echeance"||i.type==="devoir")&&(i.echeance||"")>=auj).map(i=>Object.assign({prof:r.prof},i))).sort((a,b)=>a.echeance.localeCompare(b.echeance))}function lienRejoindre(c){let q=new URLSearchParams({rejoindre:c.code,p:c.prof,m:c.matiere,c:c.classe||"",n:c.niveau||""}),base=location.href.split("?")[0].split("#")[0].replace(/[^/]*$/,"");return new URL(RACINE+"compte.html?"+q.toString(),base).href}function decoderLien(search){let q=new URLSearchParams(search||location.search),code=(q.get("rejoindre")||"").trim().toUpperCase();return code?{code,prof:(q.get("p")||"Un professeur").slice(0,60),matiere:q.get("m")||"",classe:(q.get("c")||"").slice(0,40),niveau:(q.get("n")||"").slice(0,40)}:null}var EXPLICATION=`<ul class="transparence-liste"><li><span class="oui">✓</span> un professeur te propose des exercices, des devoirs, des points de cours, des dates — jamais de note, sauf celle d'un devoir maison qu'il a choisi de noter</li><li><span class="oui">✓</span> tu vois exactement ce qu'il voit de toi, dans « Mon compte »</li><li><span class="oui">✓</span> tu peux quitter sa classe à tout moment</li><li><span class="non">✗</span> tu ne vois rien des autres élèves de la classe, et eux rien de toi</li><li><span class="non">✗</span> pas de messagerie : les messages sont choisis dans une liste, personne ne t'écrit librement</li></ul>`;export{MESSAGES,NATURES,TYPES,ICONES,profs,rejoindre,quitter,items,publier,retirer,faits,setFait,tout,trier,echeancesAVenir,lienRejoindre,decoderLien,EXPLICATION};
